let reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const soundButton=document.createElement('button');soundButton.id='sound-toggle';soundButton.className='quiet';soundButton.textContent='音：OFF';soundButton.onclick=()=>Sounds.toggle();document.querySelector('header').append(soundButton);
const motionButton=document.createElement('button');motionButton.className='quiet motion-toggle';motionButton.textContent=reducedMotion?'映像：OFF':'映像：ON';motionButton.onclick=()=>{reducedMotion=!reducedMotion;motionButton.textContent=reducedMotion?'映像：OFF':'映像：ON';applyMotion();};document.querySelector('header').append(motionButton);
function applyMotion(){document.body.classList.toggle('still',reducedMotion);document.querySelectorAll('video').forEach(v=>{if(reducedMotion)v.pause();else v.play().catch(()=>{});});}
const oldCover=cover;cover=function(){oldCover();document.querySelector('.hero').innerHTML=backdrop('exterior')+`<div class="hero-shade"></div><div class="title-copy"><span class="eyebrow">16人の個性と、すれ違う真実</span><h1>翡翠荘の<br>甘き密室</h1><p class="lead">甘い夜には、ちょっとした秘密がある。</p><p class="intro-copy">鍵のかかったケースから、自慢のモンブラン・タルトが消えた！<br>誰の言葉を信じ、どう動き回る？</p><div id="title-actions"></div><p class="thin">30ターン制 / 全6章 / セーブ機能あり / 所要1時間程度</p></div><div class="title-cast">${portrait(5,0,'cast-small')}${portrait(0,0,'cast-main')}${portrait(15,0,'cast-small')}</div>`;
const actions=$('#title-actions');actions.innerHTML=state.started?'<button class="primary" id="resume">捜査を再開する →</button><button id="new-game">最初から</button>':'<button class="primary" id="new-game">物語をはじめる →</button>';$('#new-game').onclick=()=>{if(!state.started){start();return;}modal('<h2>新しい捜査を始めますか？</h2><p>今の進行が置き換わります。</p><button class="primary" id="confirm-new">最初から始める</button>');$('#confirm-new').onclick=()=>{$('#modal').close();start();};};if($('#resume'))$('#resume').onclick=()=>{view=state.ended?'result':'board';render();};Sounds.play('bgm-title',true);applyMotion();};
const oldIntro=intro;intro=function(){oldIntro();document.querySelector('.reading').insertAdjacentHTML('afterbegin',`<div class="prologue-art">${backdrop(openingPage<2?'exterior':'pantry')}${openingPage===2?portrait(15,2,'prologue-person'):''}</div>`);applyMotion();};
const oldInvestigate=investigate;investigate=function(){oldInvestigate();if(state.turn>=30)return;const scene=selection.topic==='case'?'pantry':selection.topic==='kitchen'?'kitchen':selection.topic==='note'?'study':'hall';$('#panel').insertAdjacentHTML('afterbegin',`<div class="selected-scene">${backdrop(scene)}<div class="selected-cast">${portrait(selection.a,0,'scene-person')}${portrait(selection.b,0,'scene-person')}</div><div class="scene-caption"><span>${HISUI.people[selection.a].name} → ${HISUI.people[selection.b].name}</span><small>${{hall:'大広間',pantry:'パントリー',study:'書斎',kitchen:'厨房'}[scene]}</small></div></div>`);Sounds.play('bgm-investigation',true);applyMotion();};
const oldNotebook=notebook;notebook=function(){oldNotebook();document.querySelectorAll('.evidence').forEach((el,i)=>el.insertAdjacentHTML('afterbegin',itemArt(state.evidence[i])));$('#panel').insertAdjacentHTML('afterbegin','<span class="eyebrow">捜査手帳 / 記録画像は内容のイメージです</span>');};
let dialogueIndex=0;
conversation=function(){dialogueIndex=0;renderDialogue();};
function renderDialogue(){const e=shown,l=e.lines[dialogueIndex],finished=dialogueIndex===e.lines.length-1;const stage=e.topic==='case'?'pantry':e.topic==='kitchen'?'kitchen':e.topic==='note'?'study':'hall';const targetFace=e.outcome.includes('すれ違い')?3:dialogueIndex>=3?(e.gained.length?1:0):0;
$('#app').innerHTML=`<section class="novel"><div class="novel-top"><span>対話 ${String(e.turn).padStart(2,'0')} / ${HISUI.topics.find(t=>t[0]===e.topic)[1]}</span><button class="quiet" id="dialogue-log">会話を一覧で読む</button></div><div class="novel-stage">${backdrop(stage)}<div class="novel-cast"><div class="cast-slot ${l.speaker===HISUI.people[e.a].name?'speaking':''}">${portrait(e.a,dialogueIndex>2?1:0,'novel-person')}</div><div class="cast-slot ${l.speaker===HISUI.people[e.b].name?'speaking':''}">${portrait(e.b,targetFace,'novel-person')}</div></div><div class="dialogue-box" aria-live="polite"><span class="nameplate">${l.speaker==='地の文'?'翡翠荘':l.speaker}</span><p>${esc(l.text)}</p><div class="dialogue-controls"><button id="line-back" ${dialogueIndex===0?'disabled':''}>前の言葉</button><span>${dialogueIndex+1} / ${e.lines.length}</span>${!finished?'<button class="primary" id="line-next">次の言葉 →</button>':'<button class="primary" id="dialogue-done">手がかりを記録 →</button>'}</div></div></div></section>`;
$('#line-back').onclick=()=>{dialogueIndex--;renderDialogue();};if($('#line-next'))$('#line-next').onclick=()=>{dialogueIndex++;Sounds.play('sfx-select');renderDialogue();};if($('#dialogue-done'))$('#dialogue-done').onclick=()=>{Sounds.play(e.gained.length?'sfx-evidence':'sfx-select');modal(`<span class="eyebrow">今回の対話</span><h2>${e.outcome}</h2>${e.gained.map(k=>`<article class="mini-evidence">${itemArt(k)}<div><h3>${HISUI.E[k][0]}</h3><p>${HISUI.E[k][1]}</p></div></article>`).join('')}${e.keys.length?`<p>キーワード：${e.keys.map(k=>HISUI.K[k][1]).join(' / ')}</p>`:''}<p class="muted">記録を手帳で照合すると、重要キーワードを獲得できます。</p><button class="primary" id="finish-dialogue">${state.turn>=30?'最終推理へ':'捜査に戻る'} →</button>`);$('#finish-dialogue').onclick=()=>{$('#modal').close();view='board';tab=state.turn>=30?'final':'investigate';render();window.scrollTo(0,0);};};$('#dialogue-log').onclick=()=>modal(`<h2>会話の記録</h2>${e.lines.map(l=>`<div class="utterance"><span class="speaker">${l.speaker}</span><p>${esc(l.text)}</p></div>`).join('')}`);applyMotion();}
const oldResult=result;result=function(){oldResult();document.querySelector('.reading').insertAdjacentHTML('afterbegin',`<div class="prologue-art">${backdrop('ending',false)}${portrait(16,5,'prologue-person')}</div>`);Sounds.play('bgm-ending',true);applyMotion();};
const oldFinal=finalPanel;finalPanel=function(){oldFinal();Sounds.play('bgm-deduction',true);};
document.addEventListener('click',e=>{if(e.target.closest('[data-a],[data-b],[data-topic],[data-approach],[data-tab]'))Sounds.play('sfx-select');});
render();
